SELECT gen_random_uuid()::text, 'CIITD-2026: VIII International Conference of Young Scientists', '“Current Issues of Information Technology Development”, hosted by Pryazovskyi State Technical University with KNU and Karunya Institute as partners. Abstracts of 2–6 pages are due by 15 November 2026; participation and the ISBN book of abstracts are free.', 'CONFERENCE'::"EventType", 'OTHER'::"FacultyDivision", 'Pryazovskyi State Technical University, Dnipro', true, '2026-11-19'::timestamp, '2026-11-19'::timestamp, 'mailto:sergienko_a_v@pstu.edu?subject=CIITD-2026', '{"en":{"meta":"19 November 2026 · Online · PSTU, Dnipro","title":"CIITD-2026: VIII International Conference of Young Scientists","description":"“Current Issues of Information Technology Development”, hosted by Pryazovskyi State Technical University with KNU and Karunya Institute as partners. Abstracts of 2–6 pages are due by 15 November 2026; participation and the ISBN book of abstracts are free.","actionLabel":"Submit an abstract"},"uk":{"meta":"19 листопада 2026 · Онлайн · ПДТУ, Дніпро","title":"CIITD-2026: VIII Міжнародна конференція молодих учених","description":"«Актуальні питання розвитку інформаційних технологій» від Приазовського державного технічного університету за участі КНУ та Karunya Institute. Тези обсягом 2–6 сторінок — до 15 листопада 2026 року; участь і збірник тез з ISBN безкоштовні.","actionLabel":"Надіслати тези"}}'::jsonb, now()
