WHERE NOT EXISTS (SELECT 1 FROM "projects" WHERE "title" = 'Cyber Risks and Business Intelligence');

SELECT gen_random_uuid()::text, 'Fundamentals of Cyber Hygiene workshops', 'A #ResearchBasedStudent project integrated into the 2nd-year English for Specific Purposes course at the KNU Faculty of Information Technology. Team lead Yuliia Novichkova designed and led two COIL workshops in November for more than 50 students from KNU, Kyiv Aviation Institute and Pryazovskyi State Technical University.

Students explored cybersecurity topics and joined a panel discussion with researcher Patience Pesendorfer and external academic experts Gabriel Flacks and Azadeh Jafarnezhad. Participants received certificates.', 'COMPLETED'::"ProjectStatus", ARRAY['FIT', 'OTHER']::"FacultyDivision"[], ARRAY['Cybersecurity', 'Experiential']::text[], '{"en":{"title":"Fundamentals of Cyber Hygiene workshops","description":"A #ResearchBasedStudent project integrated into the 2nd-year English for Specific Purposes course at the KNU Faculty of Information Technology. Team lead Yuliia Novichkova designed and led two COIL workshops in November for more than 50 students from KNU, Kyiv Aviation Institute and Pryazovskyi State Technical University.\n\nStudents explored cybersecurity topics and joined a panel discussion with researcher Patience Pesendorfer and external academic experts Gabriel Flacks and Azadeh Jafarnezhad. Participants received certificates."},"uk":{"title":"Воркшопи «Основи кібергігієни»","description":"Проєкт #ResearchBasedStudent, інтегрований у курс англійської мови професійного спрямування для 2-го курсу факультету інформаційних технологій КНУ. Тімлідка Юлія Новічкова розробила й провела два COIL-воркшопи в листопаді для понад 50 студентів КНУ, Київського авіаційного інституту та Приазовського державного технічного університету.\n\nСтуденти досліджували теми кібербезпеки та взяли участь у панельній дискусії з дослідницею Patience Pesendorfer і зовнішніми академічними експертами Gabriel Flacks та Azadeh Jafarnezhad. Учасники отримали сертифікати."}}'::jsonb, NULL, '2025-11-01'::timestamp, now()
WHERE NOT EXISTS (SELECT 1 FROM "projects" WHERE "title" = 'Fundamentals of Cyber Hygiene workshops');

SELECT gen_random_uuid()::text, 'Foundations of NLP – From Text Preprocessing to Sentiment Analysis', 'A certified COIL module designed by team lead Eduard Parkhomenko, a Year 1 Master’s student in Computer Science at Taras Shevchenko National University of Kyiv.

Over eight weeks and five workshops, more than 200 students in 31 international teams from seven universities in Europe, Africa, North America and Asia worked in an interdisciplinary research-based learning environment.', 'COMPLETED'::"ProjectStatus", ARRAY['FIT', 'OTHER']::"FacultyDivision"[], ARRAY['AI & NLP', 'Cross-cultural']::text[], '{"en":{"title":"Foundations of NLP – From Text Preprocessing to Sentiment Analysis","description":"A certified COIL module designed by team lead Eduard Parkhomenko, a Year 1 Master’s student in Computer Science at Taras Shevchenko National University of Kyiv.\n\nOver eight weeks and five workshops, more than 200 students in 31 international teams from seven universities in Europe, Africa, North America and Asia worked in an interdisciplinary research-based learning environment."},"uk":{"title":"Foundations of NLP – From Text Preprocessing to Sentiment Analysis","description":"Сертифікований COIL-модуль, розроблений тімлідом Едуардом Пархоменком, магістрантом 1-го року навчання спеціальності «Комп’ютерні науки» КНУ імені Тараса Шевченка.\n\nПротягом восьми тижнів і п’яти воркшопів понад 200 студентів у 31 міжнародній команді із семи університетів Європи, Африки, Північної Америки та Азії працювали в міждисциплінарному середовищі навчання через дослідження."}}'::jsonb, NULL, '2026-02-16'::timestamp, now()
WHERE NOT EXISTS (SELECT 1 FROM "projects" WHERE "title" = 'Foundations of NLP – From Text Preprocessing to Sentiment Analysis');

SELECT gen_random_uuid()::text, 'Data-Driven Decision Making Across Borders', 'An eight-week COIL module initiated and organised by Dr Azadeh Jafar Nezhad of Coventry University. It brought together students from the Faculty of Economics of Taras Shevchenko National University of Kyiv, Coventry University and the University of Florida around modern data analytics tools and data-driven thinking.', 'COMPLETED'::"ProjectStatus", ARRAY['OTHER']::"FacultyDivision"[], ARRAY['Data Analytics', 'Cross-cultural']::text[], '{"en":{"title":"Data-Driven Decision Making Across Borders","description":"An eight-week COIL module initiated and organised by Dr Azadeh Jafar Nezhad of Coventry University. It brought together students from the Faculty of Economics of Taras Shevchenko National University of Kyiv, Coventry University and the University of Florida around modern data analytics tools and data-driven thinking."},"uk":{"title":"Data-Driven Decision Making Across Borders","description":"Восьмитижневий COIL-модуль, ініційований та організований д-ркою Azadeh Jafar Nezhad з Coventry University. Він об’єднав студентів економічного факультету КНУ імені Тараса Шевченка, Coventry University та University of Florida навколо сучасних інструментів аналізу даних і мислення на основі даних."}}'::jsonb, NULL, '2026-03-01'::timestamp, now()
WHERE NOT EXISTS (SELECT 1 FROM "projects" WHERE "title" = 'Data-Driven Decision Making Across Borders');

SELECT gen_random_uuid()::text, 'Gerontology and Data Analytics: interdisciplinary COIL with Georgia State University', 'An asynchronous interdisciplinary COIL project hosted by Georgia State University, Perimeter College, from 9 March to 18 April 2026. First-year Computer Science students from the KNU Faculty of Information Technology and Pryazovskyi State Technical University combined gerontology and data analytics with their US peers.

