INSERT INTO "publications" ("id", "slug", "type", "year", "position", "isFeatured", "readMoreLink", "coverKey", "sourceUrl", "pdfUrl", "detailSource", "content", "updatedAt") VALUES
  (gen_random_uuid()::text, 'big-data-and-ai-digital-economy', 'PAPER'::"PublicationType", 2026, 0, true, false, 'big-data-and-ai-digital-economy', NULL, 'https://archive.journal-grail.science/index.php/2710-3056/article/view/4534/4540', 'https://doi.org/10.36074/grail-of-science.01.05.2026.032', '{"en":{"title":"Big Data and AI: the foundation of the digital economy","source":"K. Kravets, A. Mekshun, A. Loban, L. Liashenko · Grail of Science, No. 67","excerpt":"Student research from a VIRaTeC COIL module, published in a Ukrainian Category B peer-reviewed journal.","detail":{"formatLabel":"Article","kindLabel":"Journal article","publishedOn":"1 May 2026","heroTitle":"Big Data and AI:","heroAccent":"the foundation of the digital economy.","lead":"Student research from a VIRaTeC COIL module, published in a Ukrainian Category B peer-reviewed journal.","readTime":"pp. 303–311","blocks":[{"kind":"paragraph","text":"The article grew out of a VIRaTeC COIL module: students explored the topic in a global virtual classroom and turned their findings into a peer-reviewed paper."},{"kind":"heading","text":"From an idea to global publication"},{"kind":"paragraph","text":"Six students of the KNU Faculty of Information Technology published two articles in Grail of Science, a Ukrainian Category B journal, issue 67, dated 1 May 2026."},{"kind":"quote","text":"“From an idea → to collaboration → to research → to global publication.”","author":"— VIRaTeC"}],"authors":"Kateryna Kravets, Anastasiia Mekshun, Anastasiia Loban, Larysa Liashenko","sourceLabel":"Grail of Science, No. 67 · DOI 10.36074/grail-of-science.01.05.2026.032"}},"uk":{"title":"Big Data and AI: the foundation of the digital economy","source":"К. Кравець, А. Мекшун, А. Лобан, Л. Ляшенко · Grail of Science, № 67","excerpt":"Студентське дослідження з COIL-модуля VIRaTeC, опубліковане в українському рецензованому журналі категорії Б.","detail":{"formatLabel":"Стаття","kindLabel":"Стаття в журналі","publishedOn":"1 травня 2026","heroTitle":"Big Data and AI:","heroAccent":"the foundation of the digital economy.","lead":"Студентське дослідження з COIL-модуля VIRaTeC, опубліковане в українському рецензованому журналі категорії Б.","readTime":"с. 303–311","blocks":[{"kind":"paragraph","text":"Стаття виросла з COIL-модуля VIRaTeC: студенти досліджували тему в глобальній віртуальній аудиторії та перетворили свої висновки на рецензовану публікацію."},{"kind":"heading","text":"Від ідеї до глобальної публікації"},{"kind":"paragraph","text":"Шестеро студентів факультету інформаційних технологій КНУ опублікували дві статті в Grail of Science — українському журналі категорії Б, випуск 67 від 1 травня 2026 року."},{"kind":"quote","text":"«Від ідеї → до співпраці → до дослідження → до глобальної публікації».","author":"— VIRaTeC"}],"authors":"Катерина Кравець, Анастасія Мекшун, Анастасія Лобан, Лариса Ляшенко","sourceLabel":"Grail of Science, № 67 · DOI 10.36074/grail-of-science.01.05.2026.032"}}}'::jsonb, now()),
  (gen_random_uuid()::text, 'ai-driven-talent-acquisition', 'PAPER'::"PublicationType", 2026, 1, false, false, 'ai-driven-talent-acquisition', NULL, 'https://archive.journal-grail.science/index.php/2710-3056/article/view/4535/4541', 'https://doi.org/10.36074/grail-of-science.01.05.2026.033', '{"en":{"title":"The economic efficiency of AI-driven talent acquisition","source":"M. Artemenko, S. Vasylyeva, M. Tymoshenko, L. Liashenko · Grail of Science, No. 67","excerpt":"Student research from a VIRaTeC COIL module, published in a Ukrainian Category B peer-reviewed journal.","detail":{"formatLabel":"Article","kindLabel":"Journal article","publishedOn":"1 May 2026","heroTitle":"The economic efficiency","heroAccent":"of AI-driven talent acquisition.","lead":"Student research from a VIRaTeC COIL module, published in a Ukrainian Category B peer-reviewed journal.","readTime":"pp. 312–321","blocks":[{"kind":"paragraph","text":"The article grew out of a VIRaTeC COIL module: students explored the topic in a global virtual classroom and turned their findings into a peer-reviewed paper."},{"kind":"heading","text":"From an idea to global publication"},{"kind":"paragraph","text":"Six students of the KNU Faculty of Information Technology published two articles in Grail of Science, a Ukrainian Category B journal, issue 67, dated 1 May 2026."},{"kind":"quote","text":"“From an idea → to collaboration → to research → to global publication.”","author":"— VIRaTeC"}],"authors":"Mariia Artemenko, Sofiia Vasylyeva, Mykhailo Tymoshenko, Larysa Liashenko","sourceLabel":"Grail of Science, No. 67 · DOI 10.36074/grail-of-science.01.05.2026.033"}},"uk":{"title":"The economic efficiency of AI-driven talent acquisition","source":"М. Артеменко, С. Васильєва, М. Тимошенко, Л. Ляшенко · Grail of Science, № 67","excerpt":"Студентське дослідження з COIL-модуля VIRaTeC, опубліковане в українському рецензованому журналі категорії Б.","detail":{"formatLabel":"Стаття","kindLabel":"Стаття в журналі","publishedOn":"1 травня 2026","heroTitle":"The economic efficiency","heroAccent":"of AI-driven talent acquisition.","lead":"Студентське дослідження з COIL-модуля VIRaTeC, опубліковане в українському рецензованому журналі категорії Б.","readTime":"с. 312–321","blocks":[{"kind":"paragraph","text":"Стаття виросла з COIL-модуля VIRaTeC: студенти досліджували тему в глобальній віртуальній аудиторії та перетворили свої висновки на рецензовану публікацію."},{"kind":"heading","text":"Від ідеї до глобальної публікації"},{"kind":"paragraph","text":"Шестеро студентів факультету інформаційних технологій КНУ опублікували дві статті в Grail of Science — українському журналі категорії Б, випуск 67 від 1 травня 2026 року."},{"kind":"quote","text":"«Від ідеї → до співпраці → до дослідження → до глобальної публікації».","author":"— VIRaTeC"}],"authors":"Марія Артеменко, Софія Васильєва, Михайло Тимошенко, Лариса Ляшенко","sourceLabel":"Grail of Science, № 67 · DOI 10.36074/grail-of-science.01.05.2026.033"}}}'::jsonb, now()),
  (gen_random_uuid()::text, 'human-ai-interaction-multilingual-teams-2026', 'PAPER'::"PublicationType", 2026, 2, false, false, NULL, 'https://doi.org/10.17721/StudLing2026.28.68-82', NULL, NULL, '{"en":{"title":"Human-AI interaction in multilingual professional teams: a pragmatic analysis","source":"K. Matukh, K. Liashenko, L. Liashenko, L. Budanova · Studia Linguistica, Vol. 28","excerpt":"A pragmatic analysis of AI-mediated communication in multilingual remote teams, based on 240 anonymised interaction logs. Studia Linguistica, 2026, pp. 68–82."},"uk":{"title":"Human-AI interaction in multilingual professional teams: a pragmatic analysis","source":"К. Матух, К. Ляшенко, Л. Ляшенко, Л. Буданова · Studia Linguistica, т. 28","excerpt":"Прагматичний аналіз комунікації за участі ШІ в багатомовних дистанційних командах на основі 240 анонімізованих журналів взаємодії. Studia Linguistica, 2026, с. 68–82."}}'::jsonb, now()),
  (gen_random_uuid()::text, 'integrating-rbl-into-coil-acit-2026', 'PAPER'::"PublicationType", 2026, 3, false, false, NULL, 'https://doi.org/10.1109/ACIT69831.2026.11700156', NULL, NULL, '{"en":{"title":"Integrating Research-Based Learning into COIL to foster students’ academic and intercultural growth","source":"I. Shcherbiak, D. Kostenko, Z. Krupnyk, L. Liashenko, K. Binytska, A. Kolesnikov · ACIT 2026","excerpt":"2026 16th International Conference on Advanced Computer Information Technologies (ACIT), pp. 1711–1716."},"uk":{"title":"Integrating Research-Based Learning into COIL to foster students’ academic and intercultural growth","source":"І. Щербяк, Д. Костенко, З. Крупник, Л. Ляшенко, К. Біницька, А. Колесніков · ACIT 2026","excerpt":"16-та Міжнародна конференція з передових комп’ютерних інформаційних технологій (ACIT 2026), с. 1711–1716."}}'::jsonb, now()),
  (gen_random_uuid()::text, 'kostiantyn-tyshchenko-legacy-conference', 'EVENT'::"PublicationType", 2026, 4, false, false, 'kostiantyn-tyshchenko-legacy-conference', 'https://philology.knu.ua/conference-dedicated-to-the-legacy-of-professor-kostiantyn-tyshchenko/', NULL, NULL, '{"en":{"title":"The Interdisciplinary Legacy of Professor Kostiantyn Tyshchenko: Digital Challenges","source":"II International Scientific Conference · KNU, 14–15 October 2026","excerpt":"Dr. Larysa Liashenko gave a plenary talk on the global student collaboration network; Olha Yezerska and Larysa Liashenko presented a joint paper."},"uk":{"title":"Міждисциплінарна спадщина професора Костянтина Тищенка: цифрові виклики","source":"ІІ Міжнародна наукова конференція · КНУ, 14–15 жовтня 2026","excerpt":"Д-р Лариса Ляшенко виступила з пленарною доповіддю про глобальну мережу студентської співпраці; Ольга Єзерська та Лариса Ляшенко представили спільну доповідь."}}'::jsonb, now()),
  (gen_random_uuid()::text, 'cross-cultural-communication-coil-2026', 'PAPER'::"PublicationType", 2026, 5, false, true, NULL, NULL, NULL, NULL, '{"en":{"title":"Cross-cultural communication strategies in virtual international collaboration: language, participation, asynchronous support and gamification in a COIL setting","source":"O. Yezerska, L. Liashenko · Tyshchenko Legacy Conference, Section 7","excerpt":"Communication strategies from an introductory NLP workshop with participants from Ukraine, the USA, Algeria and India; post-workshop survey N = 50, mean satisfaction 4.38/5."},"uk":{"title":"Cross-cultural communication strategies in virtual international collaboration: language, participation, asynchronous support and gamification in a COIL setting","source":"О. Єзерська, Л. Ляшенко · конференція пам’яті К. Тищенка, секція 7","excerpt":"Комунікаційні стратегії вступного NLP-воркшопу з учасниками з України, США, Алжиру та Індії; опитування після воркшопу N = 50, середня оцінка 4,38/5."}}'::jsonb, now()),
  (gen_random_uuid()::text, 'nlp-gis-spatial-analysis-2026', 'PAPER'::"PublicationType", 2026, 6, false, true, NULL, NULL, NULL, NULL, '{"en":{"title":"Integration of Natural Language Processing and Geographic Information Systems for data-driven spatial analysis","source":"M. Aksom, L. Liashenko · Tyshchenko Legacy Conference, Section 7","excerpt":"Turning unstructured text into spatial decisions: ML predictions combined with spatial data and visualised as an interactive heatmap."},"uk":{"title":"Integration of Natural Language Processing and Geographic Information Systems for data-driven spatial analysis","source":"М. Аксьом, Л. Ляшенко · конференція пам’яті К. Тищенка, секція 7","excerpt":"Перетворення неструктурованого тексту на просторові рішення: прогнози ML поєднано з просторовими даними та візуалізовано як інтерактивну теплову карту."}}'::jsonb, now()),
  (gen_random_uuid()::text, 'pstu-global-collaboration-framework-workshop', 'NEWS'::"PublicationType", 2026, 7, false, false, NULL, 'https://pstu.edu/uk/novyny/pdtu-doluchyvsya-do-mizhnarodnogo-vorkshopu-global-collaboration-framework-novi-mozhlyvosti-dlya-osvity-nauky-ta-mizhnarodnoyi-spivpraczi/', NULL, NULL, '{"en":{"title":"Pryazovskyi State Technical University joins the Global Collaboration Framework workshop","source":"Pryazovskyi State Technical University · 21 September 2026","excerpt":"A partner report on the VIRaTeC Global Network at KNU workshop with Dr. Kelly Tzoumis (Johns Hopkins University) on 15 September 2026."},"uk":{"title":"ПДТУ долучився до міжнародного воркшопу Global Collaboration Framework","source":"Приазовський державний технічний університет · 21 вересня 2026","excerpt":"Звіт партнера про воркшоп глобальної мережі VIRaTeC при КНУ з д-ром Келлі Цуміс (Університет Джонса Гопкінса) 15 вересня 2026 року."}}'::jsonb, now()),
  (gen_random_uuid()::text, 'from-student-ideas-to-global-research', 'EVENT'::"PublicationType", 2026, 8, false, false, NULL, 'https://www.linkedin.com/feed/update/urn:li:activity:7503727552549511168/', NULL, NULL, '{"en":{"title":"From Student Ideas to Global Research (JHU × KNU)","source":"Online · 15 September 2026","excerpt":"A guest lecture by Dr. Kelly Tzoumis (Johns Hopkins University) on turning ideas into a research article, book chapter or monograph, moderated by Dr. Larysa Liashenko and Olha Yezerska."},"uk":{"title":"Від студентських ідей до глобальних досліджень (JHU × КНУ)","source":"Онлайн · 15 вересня 2026","excerpt":"Гостьова лекція д-ра Келлі Цуміс (Університет Джонса Гопкінса) про те, як перетворити ідею на наукову статтю, розділ книги чи монографію. Модератори — д-р Лариса Ляшенко та Ольга Єзерська."}}'::jsonb, now()),
  (gen_random_uuid()::text, 'global-collaboration-framework-workshop', 'EVENT'::"PublicationType", 2026, 9, false, false, 'global-collaboration-framework-workshop', 'https://www.linkedin.com/feed/update/urn:li:activity:7506460993095434240/', NULL, NULL, '{"en":{"title":"Author-led workshop by Dr. Kelly Tzoumis (JHU): Global Collaboration Framework","source":"VIRaTeC Global Network at KNU","excerpt":"A workshop on the Johns Hopkins University Global Collaboration Framework for 54 students and faculty, and the first steps towards a collaborative book with student voices."},"uk":{"title":"Авторський воркшоп д-ра Келлі Цуміс (JHU): Global Collaboration Framework","source":"Глобальна мережа VIRaTeC при КНУ","excerpt":"Воркшоп про Global Collaboration Framework Університету Джонса Гопкінса для 54 студентів і викладачів та перші кроки до спільної книги з голосами студентів."}}'::jsonb, now()),
  (gen_random_uuid()::text, 'learning-through-experience', 'NEWS'::"PublicationType", 2026, 10, false, false, 'learning-through-experience', 'https://www.linkedin.com/feed/update/urn:li:activity:7507442054768250880/', NULL, NULL, '{"en":{"title":"Learning Through Experience: offshore wind farm negotiation with JHU","source":"Global Collaboration Framework · Johns Hopkins University","excerpt":"Students from Algeria, Cameroon, Jordan, Morocco, Ukraine and the USA negotiated the site of an offshore wind farm in a role-play initiated by Dr. Kelly Tzoumis."},"uk":{"title":"Навчання через досвід: переговори щодо офшорної вітрової електростанції з JHU","source":"Global Collaboration Framework · Університет Джонса Гопкінса","excerpt":"Студенти з Алжиру, Камеруну, Йорданії, Марокко, України та США в рольовій грі, ініційованій д-ром Келлі Цуміс, домовлялися про розташування офшорної вітрової електростанції."}}'::jsonb, now()),
  (gen_random_uuid()::text, 'digital-narratives-2026', 'EVENT'::"PublicationType", 2026, 11, false, false, 'digital-narratives-2026', 'https://philology.knu.ua/digital-narratives-ai-and-it-in-multidisciplinary-research-2026/', NULL, NULL, '{"en":{"title":"Digital Narratives: AI and IT in Multidisciplinary Research 2026","source":"Conference · KNU, 8 June 2026","excerpt":"Nearly 100 participants saw the results of certified COIL modules 2025–2026: Foundations of NLP (206 students), Cyber Hygiene (87) and Data-Driven Decision Making (67)."},"uk":{"title":"Digital Narratives: ШІ та ІТ у мультидисциплінарних дослідженнях 2026","source":"Конференція · КНУ, 8 червня 2026","excerpt":"Майже 100 учасників ознайомилися з результатами сертифікованих COIL-модулів 2025–2026 років: Foundations of NLP (206 студентів), Cyber Hygiene (87) і Data-Driven Decision Making (67)."}}'::jsonb, now()),
  (gen_random_uuid()::text, 'new-model-of-international-education', 'NEWS'::"PublicationType", 2026, 12, false, false, 'new-model-of-international-education', 'https://knu.ua/news/14058', NULL, NULL, '{"en":{"title":"The University is shaping a new model of international education","source":"Taras Shevchenko National University of Kyiv · 18 June 2026","excerpt":"KNU reports on Digital Narratives 2026 and on COIL modules authored by students, including the NLP module by Eduard Parkhomenko."},"uk":{"title":"Університет формує нову модель міжнародної освіти","source":"Київський національний університет імені Тараса Шевченка · 18 червня 2026","excerpt":"КНУ розповідає про Digital Narratives 2026 та авторські студентські COIL-модулі, зокрема модуль з NLP Едуарда Пархоменка."}}'::jsonb, now()),
  (gen_random_uuid()::text, 'data-driven-decision-making', 'NEWS'::"PublicationType", 2026, 13, false, false, NULL, 'https://www.linkedin.com/feed/update/urn:li:activity:7460424753208754176/', NULL, NULL, '{"en":{"title":"Data-Driven Decision Making Across Borders","source":"Coventry University · University of Florida · KNU Faculty of Economics","excerpt":"An 8-week COIL module on modern data analytics tools and data-driven thinking, initiated by Dr. Azadeh Jafar Nezhad (Coventry University)."},"uk":{"title":"Ухвалення рішень на основі даних без кордонів","source":"Університет Ковентрі · Університет Флориди · Економічний факультет КНУ","excerpt":"8-тижневий COIL-модуль про сучасні інструменти аналізу даних і мислення на основі даних, ініційований д-ром Азаде Джафар Нежад (Університет Ковентрі)."}}'::jsonb, now()),
  (gen_random_uuid()::text, 'global-minds-in-action', 'NEWS'::"PublicationType", 2026, 14, false, false, 'global-minds-in-action', 'https://philology.knu.ua/institute-of-philology-in-the-international-educational-space-language-as-a-driver-of-global-it-education/', NULL, NULL, '{"en":{"title":"Global Minds in Action: Foundations of NLP COIL module","source":"Institute of Philology, KNU · 20 April 2026","excerpt":"An 8-week Research-Based Learning module by Eduard Parkhomenko: about 200 students, 31 international teams and five workshops with seven universities."},"uk":{"title":"Global Minds in Action: COIL-модуль Foundations of NLP","source":"Інститут філології КНУ · 20 квітня 2026","excerpt":"8-тижневий модуль Research-Based Learning Едуарда Пархоменка: близько 200 студентів, 31 міжнародна команда та п’ять воркшопів за участі семи університетів."}}'::jsonb, now()),
  (gen_random_uuid()::text, 'navigating-cultural-hierarchies-in-asia', 'EVENT'::"PublicationType", 2026, 15, false, false, NULL, 'https://www.linkedin.com/feed/update/urn:li:activity:7427464281388085248/', NULL, NULL, '{"en":{"title":"Pre-COIL workshop: Navigating Cultural Hierarchies in Asia","source":"Online master-class · 3 February 2026","excerpt":"How cultural hierarchy in Asia shapes decision-making in project management, for 46 KNU FIT students."},"uk":{"title":"Pre-COIL воркшоп: культурні ієрархії в Азії","source":"Онлайн-майстер-клас · 3 лютого 2026","excerpt":"Як культурна ієрархія в Азії впливає на ухвалення рішень в управлінні проєктами — для 46 студентів ФІТ КНУ."}}'::jsonb, now()),
  (gen_random_uuid()::text, 'santo-tomas-coil-experience', 'NEWS'::"PublicationType", 2025, 16, false, false, NULL, 'https://enlinea.santotomas.cl/mundo-santo-tomas-2/estudiantes-de-ingenieria-en-informatica-de-santo-tomas-valdivia-destacan-en-experiencia-internacional-coil/321756/', NULL, NULL, '{"en":{"title":"Santo Tomás Valdivia computer engineering students stand out in an international COIL experience","source":"Instituto Profesional Santo Tomás · 20 August 2025","excerpt":"A partner report on the digital security COIL with KNU and the certificates awarded to Santo Tomás students."},"uk":{"title":"Студенти комп’ютерної інженерії Santo Tomás Valdivia відзначилися в міжнародному COIL-проєкті","source":"Instituto Profesional Santo Tomás · 20 серпня 2025","excerpt":"Звіт партнера про COIL із цифрової безпеки спільно з КНУ та сертифікати, вручені студентам Santo Tomás."}}'::jsonb, now()),
  (gen_random_uuid()::text, 'implementing-rbl-within-coil-modules', 'EVENT'::"PublicationType", 2025, 17, false, false, 'implementing-rbl-within-coil-modules', 'https://www.linkedin.com/feed/update/urn:li:activity:7398792569578496000/', NULL, NULL, '{"en":{"title":"Implementing Research-Based Learning within certified COIL modules","source":"IT&I-2025 International Scientific and Practical Conference","excerpt":"Outcomes of a COIL research project led by master’s teams with 127 students from six universities in Chile, Colombia, the UAE, the UK, India and Ukraine."},"uk":{"title":"Впровадження Research-Based Learning у сертифікованих COIL-модулях","source":"Міжнародна науково-практична конференція IT&I-2025","excerpt":"Результати дослідницького COIL-проєкту під керівництвом команд магістрантів за участі 127 студентів із шести університетів Чилі, Колумбії, ОАЕ, Великої Британії, Індії та України."}}'::jsonb, now()),
  (gen_random_uuid()::text, 'building-digital-resilience-hkbu', 'EVENT'::"PublicationType", 2025, 18, false, false, NULL, 'https://www.linkedin.com/feed/update/urn:li:activity:7361076388205842432/', NULL, NULL, '{"en":{"title":"Building Digital Resilience through Intercultural Exchange","source":"Summit panel · School of Continuing Education, Hong Kong Baptist University","excerpt":"COIL for Cyber Risks & Business Intelligence: how master’s students lead international projects."},"uk":{"title":"Розбудова цифрової стійкості через міжкультурний обмін","source":"Панель саміту · School of Continuing Education, Гонконзький баптистський університет","excerpt":"COIL з кіберризиків і бізнес-аналітики: як магістранти очолюють міжнародні проєкти."}}'::jsonb, now()),
