  (gen_random_uuid()::text, 'embedding-rbl-virtual-international-education-2025', 'PAPER'::"PublicationType", 2025, 23, false, false, NULL, 'https://drive.google.com/file/d/1yxwGMSE4b7l0B3YjlQHmvOkWM_3gvjK9/view', NULL, NULL, '{"en":{"title":"Embedding Research-Based Learning in virtual international education: enhancing students’ academic engagement and intercultural intelligence","source":"L. Liashenko, T. Andriichuk, O. Stepanenko, O. Krasnenko · XII IT&I satellite conference, Kyiv, 25 November 2025","excerpt":"Conference abstract, pp. 234–236."},"uk":{"title":"Embedding Research-Based Learning in virtual international education: enhancing students’ academic engagement and intercultural intelligence","source":"Л. Ляшенко, Т. Андрійчук, О. Степаненко, О. Красненко · XII сателітна конференція IT&I, Київ, 25 листопада 2025","excerpt":"Тези доповіді, с. 234–236."}}'::jsonb, now()),
  (gen_random_uuid()::text, 'advancing-cyber-hygiene-education-coil-2025', 'PAPER'::"PublicationType", 2025, 24, false, false, 'advancing-cyber-hygiene-education-coil-2025', 'https://drive.google.com/file/d/1xJuRxj-RbKQ9k4fPuh57dyxMoDhMihUV/view', NULL, NULL, '{"en":{"title":"Advancing cyber hygiene education through COIL: interactive student-led workshop on digital security","source":"Y. Novichkova, I. Parkhomenko, L. Liashenko · VII All-Ukrainian Conference of Young Scientists, PSTU, Dnipro, 19 November 2025","excerpt":"The international COIL workshop “Fundamentals of Cyber Hygiene 2.0: Advanced” on privacy protection, data collection practices and ethical hacking. Pp. 182–183."},"uk":{"title":"Advancing cyber hygiene education through COIL: interactive student-led workshop on digital security","source":"Ю. Новічкова, І. Пархоменко, Л. Ляшенко · VII Всеукраїнська конференція молодих учених, ПДТУ, Дніпро, 19 листопада 2025","excerpt":"Міжнародний COIL-воркшоп «Fundamentals of Cyber Hygiene 2.0: Advanced» про захист приватності, збирання даних і етичний хакінг. С. 182–183."}}'::jsonb, now()),
