  (gen_random_uuid()::text, 'language-of-youth-slang-2025', 'PAPER'::"PublicationType", 2025, 26, false, false, NULL, 'https://archives.mcnd.org.ua/index.php/conference-proceeding/issue/view/21.11.2025/70', NULL, NULL, '{"en":{"title":"Language of youth: English and Ukrainian slang","source":"K. Samoilenko, L. Liashenko, L. Budanova · V International Scientific Conference “Innovative Science”, 21 November 2025","excerpt":"Student research supervised by Dr. Larysa Liashenko. Pp. 384–392."},"uk":{"title":"Language of youth: English and Ukrainian slang","source":"К. Самойленко, Л. Ляшенко, Л. Буданова · V Міжнародна наукова конференція «Інноваційна наука», 21 листопада 2025","excerpt":"Студентське дослідження під керівництвом д-ра Лариси Ляшенко. С. 384–392."}}'::jsonb, now()),
